$('previous-step').addEventListener('click',guarded(async()=>{if(busy)return;await flushSave();setView(previousView,{restore:true});}));
$('settings-button').addEventListener('click',guarded(async()=>{await flushSave();setView('settings');}));
$('sidebar-toggle').addEventListener('click',()=>{document.body.classList.toggle('sidebar-hidden');$('sidebar-toggle').setAttribute('aria-label',document.body.classList.contains('sidebar-hidden')?'실험 목록 펼치기':'실험 목록 접기');});
$('close-detail').addEventListener('click',guarded(closeDetail));$('detail-dialog').addEventListener('cancel',event=>{event.preventDefault();guarded(closeDetail)();});$('examples').addEventListener('click',guarded(async event=>{const button=event.target.closest('[data-job]');if(button){const row=casePage?.rows.find(row=>String(row.ordinal)===button.dataset.case);await showDetail(button.dataset.run,button.dataset.job,row);}}));
$('detail-comparison').addEventListener('click',guarded(async event=>{const button=event.target.closest('[data-detail-job]');if(button&&reviewState)await showDetail(reviewState.id,button.dataset.detailJob,detailCase);}));
$('review-note').addEventListener('input',scheduleReview);$('review-marked').addEventListener('change',scheduleReview);
for(const id of ['case-mode','case-baseline','case-domain'])$(id).addEventListener('change',guarded(async()=>{caseOffset=0;await loadCases();}));$('case-query').addEventListener('input',()=>{clearTimeout(caseTimer);caseOffset=0;caseTimer=setTimeout(()=>loadCases().catch(error),250);});$('case-previous').addEventListener('click',guarded(async()=>{caseOffset=Math.max(0,caseOffset-25);await loadCases();}));$('case-next').addEventListener('click',guarded(async()=>{caseOffset+=25;await loadCases();}));
$('compare-documents').addEventListener('click',guarded(async()=>{await flushSave();$('document-diff').hidden=false;await loadDocumentDiff();}));$('diff-baseline').addEventListener('change',guarded(loadDocumentDiff));$('close-diff').addEventListener('click',()=>{$('document-diff').hidden=true;diffTicket++;});
document.addEventListener('selectionchange',editorTools);$('editor-tools').addEventListener('mousedown',event=>{editor.rememberSelection();if(event.target.closest('button'))event.preventDefault();});$('editor-tools').addEventListener('click',event=>{const format=event.target.closest('[data-format]'),table=event.target.closest('[data-table]');if(format)editor.format(format.dataset.format);if(table)editor.tableAction(table.dataset.table);});$('paragraph-format').addEventListener('change',()=>editor.formatBlock($('paragraph-format').value));
$('edit-link').addEventListener('click',()=>{if(frozen())return;const info=editor.linkInfo();$('link-text').value=info.text;$('link-url').value=info.url;$('link-fields').hidden=false;$('link-url').focus();});$('apply-link').addEventListener('click',guarded(async()=>{if(frozen())return;editor.applyLink($('link-text').value,$('link-url').value.trim());$('link-fields').hidden=true;}));$('cancel-link').addEventListener('click',()=>{$('link-fields').hidden=true;editor.restoreSelection();});$('insert-table').addEventListener('click',()=>editor.insertTable());
$('reload-model').addEventListener('click',guarded(async()=>{await api('/api/model/restart',{});await poll();}));$('open-home').addEventListener('click',()=>native({kind:'openHome'}));
window.appCommands={newExperiment:guarded(()=>newExperiment()),importSettings:()=>{if(!busy)$('settings-file').click();},save:guarded(flushSave),undo:()=>{$('editor').contains(document.activeElement)?editor.undo():document.execCommand('undo');},redo:()=>{$('editor').contains(document.activeElement)?editor.redo():document.execCommand('redo');},settings:guarded(async()=>{await flushSave();setView('settings');}),prepareQuit:async()=>{busy=true;renderRun();try{await flushSave();native({kind:'quitReady'});}catch(problem){busy=false;renderRun();error(problem);native({kind:'quitFailed'});}}};
if(window.ResizeObserver)new window.ResizeObserver(()=>document.documentElement.style.setProperty('--workbench-header-height',$('workbench-header').getBoundingClientRect().height+'px')).observe($('workbench-header'));
guarded(async()=>{const hasNative=Boolean(window.webkit?.messageHandlers?.native);$('export-pdf').hidden=!hasNative;$('export-format').value=hasNative?'pdf':'html';state=await api('/api/state');const prefectures=state.prefectures||[];$('panel-prefecture').innerHTML='<option value="">전체</option>'+prefectures.map(p=>'<option>'+esc(p)+'</option>').join('');renderModel();if(state.history.length)await selectExperiment(state.history[0].id);else showEmpty();setInterval(poll,1000);})();
